nusvc_pB = [0.19486882425262447, -0.3053251253304645, -0.5272712205189868]
nusvc_proba = [0.9165624579228633, 0.052345403501072786, 0.031092138576063834, 0.03004204797170043, 0.9254630891662047, 0.044494862862095044, 0.08337845711858159, 0.08424721657599042, 0.8323743263054277, 0.9755212496671125, 0.006520016122631455, 0.017958734210256067, 0.03507482854624546, 0.34271366382702034, 0.6222115076267343, 0.11347319021434295, 0.11675060242890711, 0.7697762073567499, 0.9605614751554019, 0.011237552835866114, 0.028200972008731902]

def data(n: int, p: int, nc: int):
    X = np.zeros((n, p)); y = np.zeros(n, dtype=int)
    for i in range(n):
        y[i] = i % nc
        for j in range(p):
            v = (i * 7919 + j * 104729 + i * j * 13 + j * j * 3) % 101
            X[i, j] = (v - 50.0) / 25.0 + (0.8 * y[i] if (j + y[i]) % 2 == 0 else -0.3 * y[i])
    return X, y

X, y = data(48, 4, 3)
X2, y2 = data(40, 3, 2)
yr = X[:, 0] * 1.5 - X[:, 1] + 0.3 * np.sin(np.arange(48.0))
sw = 1.0 + (np.arange(48) % 3).astype(float)
Q = X[:7] + 0.05
R = 1e-7
A = 1e-9

def dump(tag: str, m, sup, dual, icpt, nsup, dec, pred, Qx):
    check(close(m.support_, sup), tag + " support")
    check(close(m.dual_coef_, dual, R, A), tag + " dual")
    check(close(m.intercept_, icpt, R, A), tag + " intercept")
    if len(nsup) > 0:
        check(close(m.n_support_, nsup), tag + " n_support")
    check(close(m.decision_function(Qx), dec, R, A), tag + " dec")
    check(close(m.predict(Qx), pred), tag + " pred")

def dumpr(tag: str, m, sup, dual, icpt, pred):
    check(close(m.support_, sup), tag + " support")
    check(close(m.dual_coef_, dual, R, A), tag + " dual")
    check(close(m.intercept_, icpt, R, A), tag + " intercept")
    check(close(m.predict(Q), pred, R, A), tag + " pred")

dump("nusvc", NuSVC(nu=0.3).fit(X, y), nusvc_sup, nusvc_dual, nusvc_icpt, nusvc_nsup, nusvc_dec, nusvc_pred, Q)
dump("nusvc2", NuSVC(nu=0.4, kernel="linear").fit(X2, y2), nusvc2_sup, nusvc2_dual, nusvc2_icpt, nusvc2_nsup, nusvc2_dec, nusvc2_pred, X2[:7] + 0.05)
dump("nusvc ovo", NuSVC(nu=0.3, decision_function_shape="ovo", kernel="poly", degree=2).fit(X, y), nusvc_ovo_sup, nusvc_ovo_dual, nusvc_ovo_icpt, nusvc_ovo_nsup, nusvc_ovo_dec, nusvc_ovo_pred, Q)
dumpr("svr", SVR(C=2.0, epsilon=0.2).fit(X, yr), svr_sup, svr_dual, svr_icpt, svr_pred)
dumpr("svr lin", SVR(kernel="linear", C=0.5).fit(X, yr, sample_weight=sw), svr_lin_sup, svr_lin_dual, svr_lin_icpt, svr_lin_pred)
dumpr("nusvr", NuSVR(nu=0.4, C=3.0).fit(X, yr), nusvr_sup, nusvr_dual, nusvr_icpt, nusvr_pred)
oc = OneClassSVM(nu=0.2, gamma=0.3).fit(X)
check(close(oc.support_, oc_sup), "oc support"); check(close(oc.dual_coef_, oc_dual, R, A), "oc dual")
check(close(oc.intercept_, oc_icpt, R, A), "oc icpt"); check(close(oc.decision_function(Q), oc_dec, R, A), "oc dec")
check(close(oc.predict(Q), oc_pred), "oc pred"); check(close(oc.score_samples(Q), oc_ss, R, A), "oc ss")
check(close(oc.offset_, oc_off, R, A), "oc offset")
dump("svc cw", SVC(class_weight={0: 2.0, 2: 0.5}).fit(X, y, sample_weight=sw), svc_cw_sup, svc_cw_dual, svc_cw_icpt, svc_cw_nsup, svc_cw_dec, svc_cw_pred, Q)
dump("svc bal", SVC(class_weight="balanced", kernel="sigmoid", gamma=0.1).fit(X[:40], y[:40]), svc_bal_sup, svc_bal_dual, svc_bal_icpt, svc_bal_nsup, svc_bal_dec, svc_bal_pred, Q)
check(close(SVC(break_ties=True).fit(X, y).predict(Q), svc_bt_pred), "svc break ties")
check(close(SVC(kernel="linear", C=0.3).fit(X, y).coef_, svc_coef, R, A), "svc coef")
K = X @ X.T
mp = SVC(kernel="precomputed").fit(K, y)
check(close(mp.dual_coef_, svc_pre_dual, R, A), "svc precomputed dual")
mn = NuSVC(nu=0.3, probability=True, random_state=1).fit(X, y)
check(close(mn.probA_, nusvc_pA, 1e-6, 1e-8), "nusvc probA"); check(close(mn.probB_, nusvc_pB, 1e-6, 1e-8), "nusvc probB")
check(close(mn.predict_proba(Q), nusvc_proba, 1e-6, 1e-8), "nusvc proba")

if failed:
    print("TEST FAILED", failed)
    sys.exit(1)
print("OK")
